type Pair struct {
    x int
    y int
}

func countSubsequenceWithTargetSum(nums []int, k int) int {

    m := make(map[Pair]int)
    var helper func(int, int) int

    helper = func(sum, idx int) int {
        if sum == k {
            return 1
        }
        if idx == len(nums) {
            return 0
        }
        key := Pair{sum, idx}

        if val, ok := m[key]; ok {
            return val
        }

        skip := helper(sum, idx+1)

        take := 0
        if sum+nums[idx] <= k {
            take = helper(sum+nums[idx], idx+1)
        }

        m[key] = skip + take

        return m[key]
    }

    return helper(0, 0)
}
```

