from functools import lru_cache

class Solution:
    @lru_cache(None)
    def get_subsequnce_count(self, ind, nums, n, target_sum):
        if target_sum == 0:
            return 1

        if target_sum < 0 or ind == n:
            return 0

        return (
            self.get_subsequnce_count(ind + 1, nums, n, target_sum - nums[ind])
            + self.get_subsequnce_count(ind + 1, nums, n, target_sum)
        )

    def countSubsequenceWithTargetSum(self, nums, k):
        nums = tuple(nums)
        return self.get_subsequnce_count(0, nums, len(nums), k)
